\u0044\u0076\u0064\u0046\u003a\u007c\u003d\u0043\u0042\u0063\u0024\u0044\u0053\u0052\u0036\u0034\u0063\u006d\u0041\u004d\u002b\u0045\u003a\u003f\u0063\u0040\u0078\u0058\u0029\u0054\u003c\u0055\u0066\u002b\u002f\u002a\u0068\u0030\u0022\u0030\u0054\u0067\u0071\u0066\u0058\u0034\u0029\u005d\u0024\u0078\u007e\u0058\u004e\u005e\u0079\u0078\u0050\u0043\u0039\u0046\u0046\u0056\u002e\u006e\u004e\u0050\u0047\u0044\u002e\u003c\u0024\u0031\u006d\u0072\u005a\u006c\u0024\u0065\u0049\u007b\u0048\u007b\u003d\u0056\u006a\u0077\u002a\u007a\u0071\u0072\u0076\u0075\u002f\u0040\u0039\u0071\u0023\u0033\u0057\u0044\u006b\u0024\u0024\u0056\u0041\u006b\u004d\u0051\u0074\u0078\u006a\u006f\u0038\u0030\u0034\u003d\u004c\u0066\u0035\u0064\u0026\u005e\u0047\u0046\u004d\u0034\u006b\u0050\u006e\u007a\u004f\u005b\u005b\u0077\u005f\u007c\u003d\u005b\u0025\u004e\u0076\u003f\u0023\u007d\u002f\u0078\u0053\u0023\u0062\u0039\u0077\u007e\u006c\u0031\u0026\u0036\u0051\u004b\u003f\u0023\u007d\u002f\u006f\u0072\u0059\u0039\u0066\u005e\u0078\u002b\u0026\u0048\u002b\u0058\u007a\u0043\u0079\u0064\u0042\u003f\u0069\u0061\u004b\u0042\u003e\u0033\u0051\u002b\u003d\u007a\u007c\u0049\u0077\u0042\u007c\u0022\u003d\u0057\u0054\u002b\u0060\u002f\u007a\u0048\u0043\u002c\u0078\u006a\u006d\u005f\u0071\u0037\u003b\u0055\u003c\u0077\u004a\u006e\u004e\u0034\u0043\u0058\u0031\u0055\u0049\u0063\u0079\u0025\u006c\u006f\u0075\u0059\u0052\u007d\u0072\u0037\u006a\u0066\u004b\u0055\u007d\u0038\u0030\u003d\u0069\u0021\u0044\u0053\u002c\u005a\u0068\u004c\u007c\u002b\u0079\u0069\u0031\u0024\u0055\u002f\u0044\u0068\u0034\u0068\u0072\u0062\u0057\u0039\u0058\u007c\u003e\u0030\u005a\u0078\u003d\u0048\u0079\u0044\u005b\u0031\u006d\u0037\u0041\u0052\u007d\u0039\u002b\u0062\u0062\u0030\u003f\u0037\u003b\u005f\u002e\u0064\u007d\u0039\u007c\u005d\u003b\u006f\u0075\u0024\u003c\u0032\u0044\u002c\u0042\u0052\u006d\u0030\u004d\u0073\u0070\u0042\u0064\u0032\u002a\u0069\u004e\u0070\u0052\u0036\u006b\u004f\u0038\u0034\u0061\u0075\u0073\u002a\u004c\u003e\u0055\u0042\u0034\u003e\u006b\u0058\u005e\u0063\u0058\u0021\u0055\u005d\u006b\u006d\u007e\u0068\u0050\u002b\u004f\u0070\u0054\u006b\u0079\u004a\u0039\u007c\u005d\u002f\u0030\u003b\u0038\u006f\u0026\u002a\u0021\u0055\u005d\u006b\u006d\u007e\u0054\u005a\u0053\u0044\u006c\u007c\u0040\u0076\u002b\u003e\u0060\u004b\u0055\u0024\u0078\u003e\u0066\u004f\u0024\u0079\u0045\u0028\u0077\u0045\u0038\u007d\u003b\u0041\u005a\u0039\u003a\u007d\u005a\u0039\u005d\u006b\u0077\u0057\u0047\u0047\u0034\u0032\u0053\u002a\u002f\u0033\u0052\u007a\u004a\u0047\u0059\u0036\u007c\u005d\u0066\u006d\u0035\u003b\u0069\u0042\u0077\u007d\u007a\u0025\u0050\u005e\u0039\u0069\u003b\u002c\u0030\u0065\u0025\u0069\u0060\u0078\u0063\u0061\u007b\u003f\u007b\u0054\u0022\u0043\u0022\u0052\u0032\u004f\u0038\u007a\u006c\u0065\u0063\u005e\u0033\u002e\u006b\u003b\u0021\u0034\u0041\u0021\u0050\u0055\u005e\u0066\u0035\u004a\u0048\u0043\u0045\u0021\u007e\u0046\u0070\u0070\u0051\u0049\u002e\u0036\u0077\u0034\u0066\u0040\u0021\u005e\u0055\u004d\u0032\u007a\u0064\u0055\u0034\u0024\u005b\u004c\u0047\u002b\u006b\u0057\u0050\u0042\u0068\u007b\u0063\u0053\u004d\u006f\u003d\u0034\u0060\u0056\u0058\u007e\u002b\u0049\u0070\u0055\u0028\u0029\u0056\u002f\u0049\u0038\u0033\u0022\u003b\u002f\u0070\u004e\u0074\u0046\u0071\u0061\u007b\u0029\u007c\u0054\u007d\u003d\u0028\u0034\u0064\u005a\u0060\u0077\u007a\u005e\u0026\u006a\u004e\u0064\u004e\u0040\u006b\u0022\u0046\u0046\u0076\u0073\u0036\u0059\u0065\u0044\u0038\u0061\u002e\u0028\u004d\u0071\u004d\u004a\u0055\u0044\u002c\u0042\u0052\u006d\u0030\u007c\u0038\u006d\u0033\u0022\u0051\u007e\u0046\u0049\u0055\u006e\u0025\u0045\u002f\u0054\u005d\u0042\u007a\u0046\u0045\u0023\u006a\u0024\u0036\u007a\u0044\u0053\u005d\u0046\u007b\u002a\u0058\u0044\u0044\u0048\u0067\u003c\u002b\u0043\u007d\u0073\u0024\u003b\u0033\u0022\u0051\u007e\u0052\u0053\u0063\u0054\u007b\u0042\u006d\u006a\u002f\u0044\u0060\u0076\u003e\u0038\u0067\u004d\u004e\u004e\u0077\u0060\u0056\u0076\u0028\u0031\u0043\u0067\u005e\u0066\u0061\u0065\u007e\u0048\u006a\u0076\u002f\u003c\u0062\u0042\u005b\u004e\u006a\u003d\u0077\u0057\u0045\u005e\u006c\u0031\u0053\u005b\u004e\u005a\u006b\u0058\u0057\u0076\u0072\u0059\u0071\u0063\u0049\u0042\u0031\u003a\u0025\u0031\u0028\u0028\u0024\u0026\u0076\u006f\u0023\u0025\u0048\u0059\u006b\u0042\u0062\u0041\u0065\u006f\u0053\u0069\u0045\u003a\u006c\u0078\u0021\u005d\u0050\u0021\u002c\u0029\u002b\u0056\u005f\u0059\u0045\u007b\u007e\u0022\u0076\u0064\u0025\u0024\u004e\u0065\u0055\u0053\u0030\u0022\u0076\u002a\u0075\u006c\u0044\u007a\u007a\u006d\u0069\u0076\u002a\u006c\u005a\u0029\u007b\u0036\u0025\u007e\u004f\u0052\u0021\u0072\u003c\u0028\u0038\u0079\u0034\u0032\u0046\u004e\u006b\u003d\u006d\u0072\u0066\u0055\u003f\u0039\u004e\u0072\u0033\u0044\u006d\u006a\u002e\u0064\u0022\u006c\u0022\u0055\u004e\u0048\u0079\u003a\u004d\u004b\u0041\u006a\u0025\u0052\u0032\u0055\u006c\u0043\u0077\u002c\u0057\u002f\u004e\u002f\u0073\u0039\u0066\u005b\u0039\u0025\u007d\u0030\u0058\u0076\u0052\u004d\u0021\u0059\u0074\u0079\u007d\u004d\u0065\u007e\u0051\u003d\u006f\u0039\u0051\u0056\u003d\u007d\u0077\u004f\u002a\u0045\u006a\u0030\u0055\u0052\u0057\u0036\u0074\u007a\u0040\u004b\u004d\u0025\u007b\u0065\u0054\u0048\u005f\u004f\u0060\u0070\u006d\u007d\u002a\u0026\u0064\u0052\u0058\u0064\u002f\u003b\u004b\u0040\u0068\u002c\u0035\u0063\u0066\u003d\u0075\u002a\u0043\u0046\u0024\u0043\u0064\u0023\u0031\u0032\u0038\u006d\u0066\u003d\u0075\u002e\u004f\u0036\u003a\u0055\u007a\u006d\u007b\u007d\u003e\u004d\u0058\u002a\u0035\u0033\u0031\u0057\u006c\u0065\u0054\u0036\u0025\u0045\u0048\u0053\u0078\u0079\u006c\u002b\u006c\u007a\u0076\u0046\u0036\u0059\u002a\u007c\u003b\u0060\u0040\u003c\u0035\u0045\u006a\u004d\u0033\u0070\u006c\u0068\u004c\u006c\u005b\u0030\u0023\u004f\u005a\u005e\u0057\u0066\u0042\u0036\u0047\u0039\u0061\u0033\u003f\u0069\u0041\u006d\u0024\u0037\u006d\u0047\u004a\u0053\u0041\u0058\u0058\u0062\u0075\u007a\u006f\u0061\u0026\u0059\u0040\u0026\u007c\u0023\u003c\u0072\u0058\u0047\u007b\u0075\u003b\u0075\u006f\u006a\u0033\u006b\u007a\u004e\u0031\u003b\u0061\u007c\u0028\u0031\u005b\u003c\u0044\u006b\u0064\u0048\u004a\u003f\u0039\u006e\u0030\u004e\u007c\u0044\u002c\u005d\u0064\u0041\u002e\u006a\u0047\u0034\u0036\u002c\u0045\u0040\u0021\u0062\u0079\u007b\u0033\u0031\u0057\u006c\u0065\u0054\u0036\u0078\u0078\u006e\u003e\u0023\u0032\u004d\u0072\u0021\u0023\u0060\u0068\u0054\u007e\u0030\u0065\u0043\u0045\u0039\u003e\u0049\u0023\u0073\u0064\u0063\u007a\u0034\u0077\u0060\u0045\u0030\u0077\u0065\u007b\u0071\u0023\u0023\u0032\u006d\u007e\u0023\u004a\u0047\u006e\u0035\u006a\u0038\u0049\u0039\u006f\u0039\u0052\u006f\u0055\u0065\u0054\u0023\u0062\u0022\u003e\u002f\u0067\u0071\u0024\u003d\u0051\u007c\u0026\u0047\u0077\u002f\u0029\u0028\u006a\u005b\u003e\u0043\u0043\u0071\u0030\u0050\u005d\u006a\u0071\u0047\u0032\u002f\u006a\u0034\u0063\u0073\u0052\u0040\u0047\u0038\u003c\u0068\u0066\u0066\u0055\u006c\u0050\u0077\u0075\u0045\u004a\u0073\u002f\u006a\u0048\u004a\u0044\u0068\u006d\u006a\u0065\u0034\u006e\u0036\u0030\u0070\u0028\u0072\u0069\u003f\u005d\u0029\u007b\u0026\u007a\u0031\u005b\u0068\u0057\u0051\u004b\u0035\u0036\u0040\u0026\u0045\u0044\u0036\u0068\u0048\u0034\u003c\u0038\u0040\u0040\u0045\u0041\u0068\u0047\u0046\u0076\u0058\u003a\u0066\u0067\u007a\u0041\u0064\u0067\u0026\u004d\u003c\u0074\u0069\u007d\u007b\u006b\u007e\u0079\u005d\u007b\u006f\u006f\u002b\u0040\u004b\u0048\u0030\u0070\u0031\u0030\u004b\u0038\u0050\u0024\u005d\u006e\u0026\u002c\u0046\u0076\u0078\u0063\u006a\u0051\u004d\u0059\u007d\u004b\u0073\u003f\u0078\u003c\u007b\u002e\u0051\u0037\u006d\u0073\u003b\u004f\u0036\u006c\u004a\u002a\u0036\u003f\u004a\u005d\u005f\u002c\u004c\u004c\u0044\u005e\u0024\u006f\u0038\u007d\u005f\u0078\u007a\u002e\u0058\u007a\u004d\u0047\u0063\u0021\u0074\u006a\u0060\u0031\u002e\u002e\u006d\u0077\u005f\u0054\u002b\u0056\u0022\u0058\u003e\u0064\u0025\u0023\u0042\u0051\u003a\u0076\u0074\u0078\u0075\u0048\u002b\u0062\u0042\u0021\u0021\u0053\u0036\u0025\u0074\u0037\u004b\u004b\u007e\u0023\u006b\u0045\u0053\u0034\u003e\u0024\u007a\u004b\u0060\u0077\u004c\u007e\u0077\u004f\u005a\u003a\u0053\u003c\u0076\u0062\u0045\u006e\u003e\u0060\u003a\u0055\u0026\u0065\u0028\u0070\u003f\u0033\u0047\u0063\u0028\u005e\u003a\u006e\u006a\u004e\u003e\u0074\u0079\u004b\u003b\u005b\u004d\u0039\u0039\u0063\u0068\u0026\u0079\u0051\u0033\u0036\u0072\u0078\u003e\u0036\u002f\u0044\u0068\u007a\u0056\u0072\u0033\u007b\u0072\u007e\u0043\u0047\u007d\u002c\u0060\u0039\u005a\u0067\u0063\u0031\u0051\u007b\u004a\u0051\u0060\u0039\u0042\u0046\u007d\u0031\u0079\u004f\u0075\u0043\u0071\u004e\u0053\u0071\u0036\u0073\u005b\u0036\u005e\u004d\u0058\u0066\u0029\u0060\u0078\u0067\u003a\u0073\u003e\u0060\u0068\u002c\u002e\u0039\u0039\u0063\u0068\u0026\u0079\u005f\u003f\u0021\u0039\u0052\u0034\u0029\u0076\u0071\u006c\u0045\u003e\u004b\u0068\u002c\u0033\u0069\u0078\u007c\u006c\u005b\u0048\u003e\u0060\u0055\u005f\u0049\u006b\u005f\u0055\u0063\u0068\u0026\u0079\u005f\u003f\u0069\u0043\u0040\u0030\u004e\u003d\u0063\u0044\u003c\u0064\u0070\u0068\u0054\u0063\u0060\u006c\u004d\u0077\u007e\u0043\u0079\u0024\u006d\u0033\u006d\u0070\u007b\u007d\u0069\u0060\u0024\u0067\u0034\u0064\u003f\u0049\u006c\u0037\u0035\u0036\u004a\u0029\u0035\u004f\u0079\u007d\u002b\u0062\u0075\u0049\u0039\u002e\u0068\u0065\u003a\u003a\u004e\u004a\u002a\u004d\u0064\u003e\u0033\u0023\u006e\u0079\u0033\u0026\u0040\u003f\u0066\u004e\u006e\u0053\u0021\u005a\u0063\u0068\u0055\u0021\u0070\u0066\u006c\u0023\u004a\u0073\u0079\u0061\u0049\u0040\u0024\u003f\u006f\u004b\u0055\u0021\u0055\u0026\u0054\u004c\u004c\u003c\u004a\u006e\u0044\u005b\u0030\u0038\u0025\u0023\u006e\u006e\u0046\u0051\u003a\u007d\u0031\u0062\u0029\u003c\u0040\u0070\u0058\u0041\u0073\u0043\u004e\u002b\u0065\u004f\u0051\u007e\u0050\u0021\u0059\u002b\u0058\u0037\u006f\u006b\u0055\u0032\u0077\u002f\u006c\u0051\u0057\u0063\u0034\u0043\u0021\u003c\u0067\u0079\u0035\u006f\u005b\u0062\u0039\u002e\u0041\u0041\u0032\u002a\u0059\u0055\u0051\u003e\u002e\u0064\u0021\u0036\u0025\u0060\u004f\u0032\u0056\u004e\u0042\u007c\u0069\u006b\u0031\u0071\u005b\u0044\u002b\u006a\u003b\u0021\u005f\u0069\u0025\u0074\u003b\u0052\u0045\u004e\u0030\u004f\u0075\u0078\u002f\u0044\u0026\u007a\u0064\u0075\u002a\u005f\u0069\u004a\u005d\u0022\u0048\u0071\u0060\u0063\u0043\u006c\u003c\u0036\u0037\u0065\u0025\u0074\u003b\u0052\u0076\u0022\u0056\u0040\u0030\u0073\u0043\u006c\u007b\u0041\u005e\u0037\u007a\u0055\u0066\u0031\u006d\u0057\u0067\u004a\u0069\u0026\u0040\u0024\u004c\u006f\u004b\u0055\u005e\u0055\u0043\u003a\u004c\u004c\u0023\u0043\u0041\u004e\u0022\u002f\u003d\u0078\u007e\u0042\u005d\u0045\u003a\u006a\u002a\u0059\u0062\u0051\u003e\u002e\u002f\u0021\u002b\u0073\u0060\u004f\u0079\u0036\u0075\u006e\u0070\u0033\u0061\u002b\u0040\u0030\u0031\u0071\u0063\u0076\u004b\u0055\u005e\u0055\u0043\u003a\u004c\u004c\u0023\u0043\u0041\u004e\u0022\u002f\u0072\u0050\u0050\u0049\u0030\u0076\u0066\u0042\u007b\u0067\u004d\u0072\u002e\u0059\u0031\u0071\u0049\u004d\u004b\u0055\u0021\u0055\u0026\u0054\u004c\u004c\u003c\u004a\u0041\u004e\u004d\u0042\u003d\u0078\u006e\u007c\u0031\u0071\u0051\u0076\u004b\u0055\u0021\u0055\u0026\u0054\u004c\u004c\u003c\u004a\u0041\u004e\u004d\u0042\u003d\u0078\u006e\u007c\u0031\u0071\u0051\u0076\u004b\u0055\u0021\u0055\u0026\u0054\u004c\u004c\u003c\u004a\u0041\u004e\u004d\u0042\u003d\u0078\u006e\u007c\u0031\u0071\u0051\u0076\u004b\u0055\u0021\u0055\u0026\u0054\u004c\u004c\u003c\u004a\u0041\u004e\u004d\u0042\u0058\u0066\u0078\u0022\u003a\u0031\u0071\u005b\u0044\u0046\u0046\u0056\u0057\u0060\u0059\u007c\u0033\u0023\u003a\u0047\u006c\u006f\u007c\u0068\u0042\u006a\u0076\u006a\u002e\u0032\u006b\u004f\u0028\u0070\u0046\u005f\u006c\u0036\u0059\u005b\u0040\u003e\u0074\u0031\u002c\u0033\u0072\u006b\u0079\u0049\u003b\u0049\u0075\u0031\u0071\u005b\u0044\u0046\u0046\u0047\u0041\u0042\u0045\u004c\u003e\u0054\u003c\u0044\u0072\u002a\u004d\u0035\u0032\u004d\u0059\u0024\u0028\u0047\u0060\u0028\u002f\u0052\u0072\u006a\u0032\u0069\u0031\u0071\u004a\u0071